    public sealed class BattleCombatantSnapshot
    {
        private readonly List<EquipmentInstanceId> _equipment;
        public BattleCombatantSnapshot(SoldierId soldierId,UnitGroupId unitGroupId,TroopDefinitionId troopDefinitionId,CombatRoleId roleId,IEnumerable<EquipmentInstanceId> equipment,bool mounted)
        {if(!soldierId.IsValid||!unitGroupId.IsValid||!troopDefinitionId.IsValid||!roleId.IsValid)throw new ArgumentException("Combatant references are invalid.");_equipment=(equipment??throw new ArgumentNullException(nameof(equipment))).Distinct().OrderBy(x=>x).ToList();if(_equipment.Any(x=>!x.IsValid))throw new ArgumentException("Equipment reference is invalid.");SoldierId=soldierId;UnitGroupId=unitGroupId;TroopDefinitionId=troopDefinitionId;CombatRoleId=roleId;IsMounted=mounted;}
        public SoldierId SoldierId{get;}public UnitGroupId UnitGroupId{get;}public TroopDefinitionId TroopDefinitionId{get;}public CombatRoleId CombatRoleId{get;}public IReadOnlyList<EquipmentInstanceId> OrderedEquipment=>_equipment;public bool IsMounted{get;}
    }

    public sealed class BattleUnitSnapshot
    {
        private readonly SortedDictionary<SoldierId,BattleCombatantSnapshot> _combatants;
        public BattleUnitSnapshot(ArmyId armyId,UnitGroupId unitGroupId,CharacterId? commanderId,long campaignHeadcount,IEnumerable<BattleCombatantSnapshot> combatants,MoraleAssessment morale,FatigueAssessment fatigue,DisciplineAssessment discipline)
        {if(!armyId.IsValid||!unitGroupId.IsValid||campaignHeadcount<0)throw new ArgumentException("Unit snapshot is invalid.");_combatants=new SortedDictionary<SoldierId,BattleCombatantSnapshot>();foreach(var x in combatants??throw new ArgumentNullException(nameof(combatants))){if(x==null||!x.UnitGroupId.Equals(unitGroupId)||_combatants.ContainsKey(x.SoldierId))throw new InvalidOperationException("Combatant snapshot does not belong to the Unit Group or is duplicated.");_combatants.Add(x.SoldierId,x);}if(_combatants.Count>campaignHeadcount)throw new InvalidOperationException("Instantiated Soldier count cannot exceed aggregate headcount.");ArmyId=armyId;UnitGroupId=unitGroupId;CommanderId=commanderId;CampaignHeadcount=campaignHeadcount;Morale=morale;Fatigue=fatigue;Discipline=discipline;}
        public ArmyId ArmyId{get;}public UnitGroupId UnitGroupId{get;}public CharacterId? CommanderId{get;}public long CampaignHeadcount{get;}public long AggregateNonInstantiatedStrength=>CampaignHeadcount-_combatants.Count;public IReadOnlyCollection<BattleCombatantSnapshot> OrderedCombatants=>_combatants.Values;public MoraleAssessment Morale{get;}public FatigueAssessment Fatigue{get;}public DisciplineAssessment Discipline{get;}
    }

    public sealed class BattleParticipantSnapshot
    {
        private readonly SortedDictionary<UnitGroupId,BattleUnitSnapshot> _units;
        private readonly SortedDictionary<TradeGoodId,long> _supply;
        public BattleParticipantSnapshot(ArmyId armyId,CharacterId commanderId,IEnumerable<BattleUnitSnapshot> units,IEnumerable<KeyValuePair<TradeGoodId,long>> supply)
        {if(!armyId.IsValid||!commanderId.IsValid)throw new ArgumentException("Participant references are invalid.");_units=new SortedDictionary<UnitGroupId,BattleUnitSnapshot>();foreach(var x in units??throw new ArgumentNullException(nameof(units))){if(x==null||!x.ArmyId.Equals(armyId)||_units.ContainsKey(x.UnitGroupId))throw new InvalidOperationException("Unit snapshot is invalid or duplicated.");_units.Add(x.UnitGroupId,x);}_supply=new SortedDictionary<TradeGoodId,long>();foreach(var x in supply??throw new ArgumentNullException(nameof(supply))){if(!x.Key.IsValid||x.Value<0||_supply.ContainsKey(x.Key))throw new InvalidOperationException("Supply snapshot is invalid or duplicated.");_supply.Add(x.Key,x.Value);}ArmyId=armyId;CommanderId=commanderId;}
        public ArmyId ArmyId{get;}public CharacterId CommanderId{get;}public IReadOnlyCollection<BattleUnitSnapshot> OrderedUnits=>_units.Values;public IReadOnlyDictionary<TradeGoodId,long> OrderedSupply=>_supply;
    }

    public sealed class BattleSideState
    {
        private readonly SortedDictionary<ArmyId,BattleParticipantSnapshot> _participants=new SortedDictionary<ArmyId,BattleParticipantSnapshot>();
        public BattleSideState(BattleSideId id,CharacterId commanderId,IEnumerable<BattleParticipantSnapshot> participants){if(!id.IsValid||!commanderId.IsValid)throw new ArgumentException("Battle side is invalid.");Id=id;CommanderId=commanderId;foreach(var x in participants??throw new ArgumentNullException(nameof(participants))){if(x==null||_participants.ContainsKey(x.ArmyId))throw new InvalidOperationException("Battle participant is duplicated.");_participants.Add(x.ArmyId,x);}if(_participants.Count==0)throw new ArgumentException("Battle side needs a participant.");}
        public BattleSideId Id{get;}public CharacterId CommanderId{get;}public IReadOnlyCollection<BattleParticipantSnapshot> OrderedParticipants=>_participants.Values;public bool ContainsArmy(ArmyId id)=>_participants.ContainsKey(id);
    }

    public sealed class BattleSector
    {
        private readonly SortedSet<BattleSectorId> _adjacent=new SortedSet<BattleSectorId>();private readonly SortedSet<BattleTerrainTag> _terrain=new SortedSet<BattleTerrainTag>();private readonly SortedSet<BattleSideId> _eligibleSides=new SortedSet<BattleSideId>();
        public BattleSector(BattleSectorId id,IEnumerable<BattleTerrainTag>? terrain=null,IEnumerable<BattleSideId>? eligibleSides=null){if(!id.IsValid)throw new ArgumentException(nameof(id));Id=id;foreach(var x in terrain??Array.Empty<BattleTerrainTag>()){if(!Enum.IsDefined(typeof(BattleTerrainTag),x)||!_terrain.Add(x))throw new ArgumentException("Terrain tag is invalid or duplicated.");}foreach(var x in eligibleSides??Array.Empty<BattleSideId>()){if(!x.IsValid||!_eligibleSides.Add(x))throw new ArgumentException("Eligible side is invalid or duplicated.");}}
        public BattleSectorId Id{get;}public IReadOnlyCollection<BattleSectorId> OrderedAdjacent=>_adjacent;public IReadOnlyCollection<BattleTerrainTag> OrderedTerrain=>_terrain;public IReadOnlyCollection<BattleSideId> OrderedEligibleSides=>_eligibleSides;public bool Allows(BattleSideId side)=>_eligibleSides.Count==0||_eligibleSides.Contains(side);internal void Connect(BattleSectorId other){if(!other.IsValid||other.Equals(Id)||!_adjacent.Add(other))throw new InvalidOperationException("Sector adjacency is invalid or duplicated.");}public bool IsAdjacent(BattleSectorId other)=>_adjacent.Contains(other);
    }

    public sealed class BattleSectorGraph
    {
        private readonly SortedDictionary<BattleSectorId,BattleSector> _sectors=new SortedDictionary<BattleSectorId,BattleSector>();public IReadOnlyCollection<BattleSector> OrderedSectors=>_sectors.Values;public void Add(BattleSector sector){if(sector==null||_sectors.ContainsKey(sector.Id))throw new InvalidOperationException("Sector is null or duplicated.");_sectors.Add(sector.Id,sector);}public BattleSector GetRequired(BattleSectorId id){if(!_sectors.TryGetValue(id,out var value))throw new KeyNotFoundException("Battle sector was not found.");return value;}public void Connect(BattleSectorId first,BattleSectorId second){var a=GetRequired(first);var b=GetRequired(second);a.Connect(second);b.Connect(first);}
    }

    public sealed class BattleDeployment
