        public BattleDeployment(DeploymentGroupId id,BattleSideId sideId,ArmyId armyId,UnitGroupId unitGroupId,BattleSectorId sectorId,BattleFormation formation,bool reserve=false){if(!id.IsValid||!sideId.IsValid||!armyId.IsValid||!unitGroupId.IsValid||!sectorId.IsValid||!Enum.IsDefined(typeof(BattleFormation),formation))throw new ArgumentException("Deployment is invalid.");Id=id;SideId=sideId;ArmyId=armyId;UnitGroupId=unitGroupId;SectorId=sectorId;Formation=formation;IsReserve=reserve;}public DeploymentGroupId Id{get;}public BattleSideId SideId{get;}public ArmyId ArmyId{get;}public UnitGroupId UnitGroupId{get;}public BattleSectorId SectorId{get;private set;}public BattleFormation Formation{get;private set;}public bool IsReserve{get;}internal void Move(BattleSectorId sector)=>SectorId=sector;internal void ChangeFormation(BattleFormation formation)=>Formation=formation;
    }

    public sealed class BattleOrder
    {
        public BattleOrder(BattleOrderId id,long sequence,BattleOrderKind kind,BattleSideId sideId,CharacterId issuerId,DeploymentGroupId groupId,BattleSectorId? targetSector=null,DeploymentGroupId? targetGroup=null,BattleFormation? formation=null){if(!id.IsValid||sequence<0||!Enum.IsDefined(typeof(BattleOrderKind),kind)||!sideId.IsValid||!issuerId.IsValid||!groupId.IsValid)throw new ArgumentException("Battle order is invalid.");Id=id;Sequence=sequence;Kind=kind;SideId=sideId;IssuerId=issuerId;GroupId=groupId;TargetSector=targetSector;TargetGroup=targetGroup;Formation=formation;}public BattleOrderId Id{get;}public long Sequence{get;}public BattleOrderKind Kind{get;}public BattleSideId SideId{get;}public CharacterId IssuerId{get;}public DeploymentGroupId GroupId{get;}public BattleSectorId? TargetSector{get;}public DeploymentGroupId? TargetGroup{get;}public BattleFormation? Formation{get;}
    }

    public sealed class BattleAttackIntent
    {
        public BattleAttackIntent(DeploymentGroupId attackerGroup,SoldierId attacker,SoldierId target,EquipmentInstanceId weapon,AttackMode attackMode,DamageType damageType){if(!attackerGroup.IsValid||!attacker.IsValid||!target.IsValid||!weapon.IsValid||!Enum.IsDefined(typeof(AttackMode),attackMode)||!Enum.IsDefined(typeof(DamageType),damageType))throw new ArgumentException("Attack intent is invalid.");AttackerGroup=attackerGroup;Attacker=attacker;Target=target;Weapon=weapon;AttackMode=attackMode;DamageType=damageType;}public DeploymentGroupId AttackerGroup{get;}public SoldierId Attacker{get;}public SoldierId Target{get;}public EquipmentInstanceId Weapon{get;}public AttackMode AttackMode{get;}public DamageType DamageType{get;}
