    public sealed class BattleAmmoAllocation
    {public BattleAmmoAllocation(SoldierId soldierId,AmmoFamilyId familyId,long quantity){if(!soldierId.IsValid||!familyId.IsValid||quantity<0)throw new ArgumentException("Ammunition allocation is invalid.");SoldierId=soldierId;FamilyId=familyId;Quantity=quantity;}public SoldierId SoldierId{get;}public AmmoFamilyId FamilyId{get;}public long Quantity{get;private set;}internal void Consume(long quantity){if(quantity<=0||quantity>Quantity)throw new InvalidOperationException("Battle ammunition is insufficient.");Quantity-=quantity;}}
    public sealed class BattleAmmunitionState
    {private readonly SortedDictionary<string,BattleAmmoAllocation> _items=new SortedDictionary<string,BattleAmmoAllocation>(StringComparer.Ordinal);public IReadOnlyCollection<BattleAmmoAllocation> OrderedAllocations=>_items.Values;public void Add(BattleAmmoAllocation item){if(item==null)throw new ArgumentNullException(nameof(item));var key=Key(item.SoldierId,item.FamilyId);if(_items.ContainsKey(key))throw new InvalidOperationException("Ammunition allocation is duplicated.");_items.Add(key,item);}public long QuantityOf(SoldierId soldier,AmmoFamilyId family)=>_items.TryGetValue(Key(soldier,family),out var x)?x.Quantity:0;public void Consume(SoldierId soldier,AmmoFamilyId family,long quantity){if(!_items.TryGetValue(Key(soldier,family),out var x))throw new InvalidOperationException("No battle ammunition allocation exists.");x.Consume(quantity);}private static string Key(SoldierId soldier,AmmoFamilyId family)=>soldier.Value+"\n"+family.Value;}

