    public sealed class BattleResult
    {
        public BattleResult(BattleId battleId,BattleEndReason endReason,WorldTimestamp completedAt,long elapsedSteps,BattleSideId? winningSide,IEnumerable<BattleUnitOutcome> units,IEnumerable<BattleSoldierOutcome> soldiers,IEnumerable<BattleCharacterOutcome>? characters=null,IEnumerable<BattleSideId>? participatingSides=null,IEnumerable<BattleAmmoOutcome>? ammunition=null){if(!battleId.IsValid||!Enum.IsDefined(typeof(BattleEndReason),endReason)||elapsedSteps<0)throw new ArgumentException("Battle result is invalid.");BattleId=battleId;EndReason=endReason;CompletedAt=completedAt;ElapsedSteps=elapsedSteps;WinningSide=winningSide;OrderedParticipatingSides=(participatingSides??throw new ArgumentNullException(nameof(participatingSides))).OrderBy(x=>x).ToList();OrderedUnitOutcomes=(units??throw new ArgumentNullException(nameof(units))).OrderBy(x=>x.UnitGroupId).ToList();OrderedSoldierOutcomes=(soldiers??throw new ArgumentNullException(nameof(soldiers))).OrderBy(x=>x.SoldierId).ToList();OrderedCharacterOutcomes=(characters??Array.Empty<BattleCharacterOutcome>()).OrderBy(x=>x.CharacterId).ToList();OrderedAmmunitionOutcomes=(ammunition??Array.Empty<BattleAmmoOutcome>()).OrderBy(x=>x.SoldierId).ThenBy(x=>x.FamilyId).ToList();if(OrderedParticipatingSides.Count<2||OrderedParticipatingSides.Any(x=>!x.IsValid)||OrderedParticipatingSides.Distinct().Count()!=OrderedParticipatingSides.Count||OrderedUnitOutcomes.Select(x=>x.UnitGroupId).Distinct().Count()!=OrderedUnitOutcomes.Count||OrderedSoldierOutcomes.Select(x=>x.SoldierId).Distinct().Count()!=OrderedSoldierOutcomes.Count||OrderedCharacterOutcomes.Select(x=>x.CharacterId).Distinct().Count()!=OrderedCharacterOutcomes.Count||OrderedAmmunitionOutcomes.Select(x=>x.SoldierId.Value+"\n"+x.FamilyId.Value).Distinct(StringComparer.Ordinal).Count()!=OrderedAmmunitionOutcomes.Count)throw new InvalidOperationException("Battle result outcomes are invalid or duplicated.");}
        public BattleId BattleId{get;}public BattleEndReason EndReason{get;}public WorldTimestamp CompletedAt{get;}public long ElapsedSteps{get;}public BattleSideId? WinningSide{get;}public IReadOnlyList<BattleSideId> OrderedParticipatingSides{get;}public IReadOnlyList<BattleUnitOutcome> OrderedUnitOutcomes{get;}public IReadOnlyList<BattleSoldierOutcome> OrderedSoldierOutcomes{get;}public IReadOnlyList<BattleCharacterOutcome> OrderedCharacterOutcomes{get;}public IReadOnlyList<BattleAmmoOutcome> OrderedAmmunitionOutcomes{get;}
    }

    public sealed class BattleState
    {
        private readonly SortedDictionary<BattleSideId,BattleSideState> _sides=new SortedDictionary<BattleSideId,BattleSideState>();private readonly SortedDictionary<DeploymentGroupId,BattleDeployment> _deployments=new SortedDictionary<DeploymentGroupId,BattleDeployment>();private readonly SortedDictionary<BattleOrderId,BattleOrder> _orders=new SortedDictionary<BattleOrderId,BattleOrder>();private readonly List<BattleCombatOutcome> _events=new List<BattleCombatOutcome>();
        public BattleState(BattleId id,WorldTimestamp startedAt,RandomState randomState,IEnumerable<BattleSideState> sides,BattleSectorGraph sectors,BattleAmmunitionState? ammunition=null,BattleLifecycle lifecycle=BattleLifecycle.Preparing,long step=0,bool reconciled=false){if(!id.IsValid||step<0||!Enum.IsDefined(typeof(BattleLifecycle),lifecycle))throw new ArgumentException("Battle state is invalid.");Id=id;StartedAt=startedAt;RandomState=randomState;Sectors=sectors??throw new ArgumentNullException(nameof(sectors));Ammunition=ammunition??new BattleAmmunitionState();Lifecycle=lifecycle;Step=step;IsReconciled=reconciled;foreach(var x in sides??throw new ArgumentNullException(nameof(sides))){if(x==null||_sides.ContainsKey(x.Id))throw new InvalidOperationException("Battle side is duplicated.");_sides.Add(x.Id,x);}if(_sides.Count<2)throw new ArgumentException("Battle requires at least two sides.");}
        public BattleId Id{get;}public WorldTimestamp StartedAt{get;}public BattleLifecycle Lifecycle{get;private set;}public long Step{get;private set;}public RandomState RandomState{get;private set;}public bool IsReconciled{get;private set;}public BattleResult? Result{get;private set;}public BattleSectorGraph Sectors{get;}public BattleAmmunitionState Ammunition{get;}public IReadOnlyCollection<BattleSideState> OrderedSides=>_sides.Values;public IReadOnlyCollection<BattleDeployment> OrderedDeployments=>_deployments.Values;public IReadOnlyCollection<BattleOrder> OrderedOrders=>_orders.Values;public IReadOnlyList<BattleCombatOutcome> OrderedEvents=>_events;
        public void BeginDeployment(){Transition(BattleLifecycle.Preparing,BattleLifecycle.Deployment);}public void BeginActive(){if(_deployments.Count==0)throw new InvalidOperationException("At least one deployment is required.");Transition(BattleLifecycle.Deployment,BattleLifecycle.Active);}public void BeginResolving()=>Transition(BattleLifecycle.Active,BattleLifecycle.Resolving);public void Abort(){if(Lifecycle==BattleLifecycle.Completed||Lifecycle==BattleLifecycle.Aborted)throw new InvalidOperationException("Battle is terminal.");Lifecycle=BattleLifecycle.Aborted;}
        public void Deploy(BattleDeployment deployment){if(Lifecycle!=BattleLifecycle.Deployment)throw new InvalidOperationException("Deployment phase is not active.");if(deployment==null||_deployments.ContainsKey(deployment.Id)||_deployments.Values.Any(x=>x.UnitGroupId.Equals(deployment.UnitGroupId)))throw new InvalidOperationException("Deployment is null or duplicates a Unit Group.");var side=GetSide(deployment.SideId);if(!side.ContainsArmy(deployment.ArmyId))throw new InvalidOperationException("Army does not participate on the deployment side.");var participant=side.OrderedParticipants.Single(x=>x.ArmyId.Equals(deployment.ArmyId));if(!participant.OrderedUnits.Any(x=>x.UnitGroupId.Equals(deployment.UnitGroupId)))throw new InvalidOperationException("Unit Group does not participate.");if(!Sectors.GetRequired(deployment.SectorId).Allows(deployment.SideId))throw new InvalidOperationException("Sector does not allow this side.");_deployments.Add(deployment.Id,deployment);}
        public void Issue(BattleOrder order){if(Lifecycle!=BattleLifecycle.Active)throw new InvalidOperationException("Orders require an active battle.");if(order==null||_orders.ContainsKey(order.Id)||_orders.Values.Any(x=>x.Sequence==order.Sequence))throw new InvalidOperationException("Order is null or duplicated.");var group=GetDeployment(order.GroupId);if(!group.SideId.Equals(order.SideId)||!CanCommand(order.SideId,order.IssuerId,group))throw new InvalidOperationException("Issuer lacks command authority.");if(order.Kind==BattleOrderKind.MoveSector||order.Kind==BattleOrderKind.Advance){if(!order.TargetSector.HasValue||!Sectors.GetRequired(group.SectorId).IsAdjacent(order.TargetSector.Value))throw new InvalidOperationException("Movement target is not adjacent.");group.Move(order.TargetSector.Value);}if(order.Kind==BattleOrderKind.Attack){if(!order.TargetGroup.HasValue||GetDeployment(order.TargetGroup.Value).SideId.Equals(order.SideId))throw new InvalidOperationException("Attack target must be hostile.");}if(order.Kind==BattleOrderKind.ChangeFormation){if(!order.Formation.HasValue)throw new InvalidOperationException("Formation order needs a formation.");group.ChangeFormation(order.Formation.Value);}_orders.Add(order.Id,order);Step++;}
        public void Record(BattleCombatOutcome outcome,RandomState nextRandomState){if(Lifecycle!=BattleLifecycle.Active||outcome==null||_events.Any(x=>x.EventId.Equals(outcome.EventId)||x.Sequence==outcome.Sequence))throw new InvalidOperationException("Combat outcome is invalid or duplicated.");RequireCombatant(outcome.Target);_events.Add(outcome);_events.Sort((a,b)=>a.Sequence.CompareTo(b.Sequence));RandomState=nextRandomState;Step++;}
        public void Complete(BattleResult result){if(Lifecycle!=BattleLifecycle.Resolving||result==null||!result.BattleId.Equals(Id)||result.CompletedAt.CompareTo(StartedAt)<0||!result.OrderedParticipatingSides.SequenceEqual(_sides.Keys)||!AmmoMatches(result))throw new InvalidOperationException("Battle cannot complete with this result.");Result=result;Lifecycle=BattleLifecycle.Completed;}
        public void MarkReconciled(){if(Lifecycle!=BattleLifecycle.Completed||Result==null||IsReconciled)throw new InvalidOperationException("Battle result cannot be reconciled.");IsReconciled=true;}
        public void RestoreDeployment(BattleDeployment deployment){if(deployment==null||_deployments.ContainsKey(deployment.Id)||_deployments.Values.Any(x=>x.UnitGroupId.Equals(deployment.UnitGroupId)))throw new InvalidOperationException("Restored deployment is invalid or duplicated.");_deployments.Add(deployment.Id,deployment);}public void RestoreOrder(BattleOrder order){if(order==null||_orders.ContainsKey(order.Id)||_orders.Values.Any(x=>x.Sequence==order.Sequence))throw new InvalidOperationException("Restored order is invalid or duplicated.");_orders.Add(order.Id,order);}public void RestoreEvent(BattleCombatOutcome outcome){if(outcome==null||_events.Any(x=>x.EventId.Equals(outcome.EventId)||x.Sequence==outcome.Sequence))throw new InvalidOperationException("Restored battle event is invalid or duplicated.");_events.Add(outcome);_events.Sort((a,b)=>a.Sequence.CompareTo(b.Sequence));}public void RestoreResult(BattleResult result){if(result==null||!result.BattleId.Equals(Id)||Lifecycle!=BattleLifecycle.Completed||!result.OrderedParticipatingSides.SequenceEqual(_sides.Keys)||!AmmoMatches(result))throw new InvalidOperationException("Restored result conflicts with battle state.");Result=result;}
        public BattleSideState GetSide(BattleSideId id){if(!_sides.TryGetValue(id,out var value))throw new KeyNotFoundException("Battle side was not found.");return value;}public BattleDeployment GetDeployment(DeploymentGroupId id){if(!_deployments.TryGetValue(id,out var value))throw new KeyNotFoundException("Deployment was not found.");return value;}public BattleCombatantSnapshot RequireCombatant(SoldierId id){foreach(var side in _sides.Values)foreach(var p in side.OrderedParticipants)foreach(var u in p.OrderedUnits)foreach(var c in u.OrderedCombatants)if(c.SoldierId.Equals(id))return c;throw new KeyNotFoundException("Battle combatant was not found.");}
        private bool CanCommand(BattleSideId sideId,CharacterId characterId,BattleDeployment group){var side=GetSide(sideId);if(side.CommanderId.Equals(characterId))return true;var participant=side.OrderedParticipants.Single(x=>x.ArmyId.Equals(group.ArmyId));if(participant.CommanderId.Equals(characterId))return true;var unit=participant.OrderedUnits.Single(x=>x.UnitGroupId.Equals(group.UnitGroupId));return unit.CommanderId.HasValue&&unit.CommanderId.Value.Equals(characterId);}private bool AmmoMatches(BattleResult result){var current=Ammunition.OrderedAllocations.Select(x=>x.SoldierId.Value+"\n"+x.FamilyId.Value+"\n"+x.Quantity).ToList();var reported=result.OrderedAmmunitionOutcomes.Select(x=>x.SoldierId.Value+"\n"+x.FamilyId.Value+"\n"+x.RemainingQuantity).ToList();return current.SequenceEqual(reported,StringComparer.Ordinal);}private void Transition(BattleLifecycle from,BattleLifecycle to){if(Lifecycle!=from)throw new InvalidOperationException("Invalid battle lifecycle transition.");Lifecycle=to;} 
    }

    public sealed class BattleRegistry
    {
        private readonly SortedDictionary<BattleId,BattleState> _items=new SortedDictionary<BattleId,BattleState>();public IReadOnlyCollection<BattleState> OrderedBattles=>_items.Values;public void Add(BattleState battle){if(battle==null||_items.ContainsKey(battle.Id))throw new InvalidOperationException("Battle is null or duplicated.");_items.Add(battle.Id,battle);}public BattleState GetRequired(BattleId id){if(!_items.TryGetValue(id,out var value))throw new KeyNotFoundException("Battle was not found.");return value;}public bool Contains(BattleId id)=>_items.ContainsKey(id);
    }
    public sealed class BattleCampaignState{public BattleCampaignState(BattleRegistry? battles=null){Battles=battles??new BattleRegistry();}public BattleRegistry Battles{get;}}
